pub fn dag_emit_check_ref_target(
    node: Rc<Node>,
    key_to_id: Rc<HashMap<String, String>>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    match v1_rt::map_get(
        &key_to_id,
        crate::v1_compiler_dag_collect::dag_node_key(node.clone()),
    ) {
        Some(_) => Rc::new(vec![]),
        std::option::Option::None => Rc::new(vec![dag_node_missing_ref_error(node.clone())]),
    }
}

pub fn dag_emit_check_optional_ref_target(
    value: Option<Rc<Node>>,
    key_to_id: Rc<HashMap<String, String>>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    match value.clone() {
        Some(inner) => dag_emit_check_ref_target(inner.clone(), key_to_id.clone()),
        std::option::Option::None => Rc::new(vec![]),
    }
}

pub fn dag_emit_check_inferred_ref_target(
    value: Option<Rc<InferredNode>>,
    key_to_id: Rc<HashMap<String, String>>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    match value.clone().as_deref().cloned() {
        Some(InferredNode::Resolved { node: n, .. }) => {
            dag_emit_check_ref_target(n.clone(), key_to_id.clone())
        }
        _ => Rc::new(vec![]),
    }
}

pub fn dag_emit_check_node_refs(
    node: Rc<Node>,
    key_to_id: Rc<HashMap<String, String>>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    v1_rt::concat(
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                if is_import_statement_node(node.clone()) {
                                    Rc::new(vec![])
                                } else {
                                    Rc::new({
                                        let mut __result = Vec::new();
                                        for c in node.children.clone().iter().cloned() {
                                            __result.extend(
                                                (*dag_emit_check_ref_target(
                                                    c.clone(),
                                                    key_to_id.clone(),
                                                ))
                                                .iter()
                                                .cloned(),
                                            );
                                        }
                                        __result
                                    })
                                },
                                if crate::v1_compiler_dag_collect::is_module_shell_node(
                                    node.clone(),
                                ) {
                                    Rc::new(vec![])
                                } else {
                                    Rc::new({
                                        let mut __result = Vec::new();
                                        for p in node.params.clone().iter().cloned() {
                                            __result.extend(
                                                (*dag_emit_check_ref_target(
                                                    p.clone(),
                                                    key_to_id.clone(),
                                                ))
                                                .iter()
                                                .cloned(),
                                            );
                                        }
                                        __result
                                    })
                                },
                            ),
                            Rc::new({
                                let mut __result = Vec::new();
                                for u in node.uses.clone().iter().cloned() {
                                    __result.extend(
                                        (*dag_emit_check_ref_target(u.clone(), key_to_id.clone()))
                                            .iter()
                                            .cloned(),
                                    );
                                }
                                __result
                            }),
                        ),
                        dag_emit_check_optional_ref_target(node.body.clone(), key_to_id.clone()),
                    ),
                    dag_emit_check_optional_ref_target(node.transport.clone(), key_to_id.clone()),
                ),
                Rc::new({
                    let mut __result = Vec::new();
                    for p in node.properties.clone().iter().cloned() {
                        __result.extend(
                            (*dag_emit_check_ref_target(p.clone(), key_to_id.clone()))
                                .iter()
                                .cloned(),
                        );
                    }
                    __result
                }),
            ),
            dag_emit_check_optional_ref_target(node.type_annotation.clone(), key_to_id.clone()),
        ),
        v1_rt::concat(
            dag_emit_check_inferred_ref_target(node.inferred.clone(), key_to_id.clone()),
            match (*node.expr_data.clone()).clone() {
                ExprData::ExprCall { call_semantics, .. } => match call_semantics.clone() {
                    Some(semantics) => match (*semantics.clone()).clone() {
                        CallSemantics::ResolvedDirectCallSemantics {
                            application_plan: plan,
                            ..
                        } => Rc::new({
                            let mut __result = Vec::new();
                            for application in plan.iter().cloned() {
                                __result.extend(
                                    (*v1_rt::concat(
                                        dag_emit_check_ref_target(
                                            application.formal.clone().declared_type.clone(),
                                            key_to_id.clone(),
                                        ),
                                        v1_rt::concat(
                                            dag_emit_check_ref_target(
                                                application
                                                    .formal
                                                    .clone()
                                                    .declaration_bound_conformance
                                                    .clone(),
                                                key_to_id.clone(),
                                            ),
                                            dag_emit_check_ref_target(
                                                application
                                                    .formal
                                                    .clone()
                                                    .substitution_basis
                                                    .clone(),
                                                key_to_id.clone(),
                                            ),
                                        ),
                                    ))
                                    .iter()
                                    .cloned(),
                                );
                            }
                            __result
                        }),
                        _ => Rc::new(vec![]),
                    },
                    std::option::Option::None => Rc::new(vec![]),
                },
                _ => Rc::new(vec![]),
            },
        ),
    )
}

pub fn dag_emit_ref_errors(
    order: Rc<Vec<Rc<Node>>>,
    key_to_id: Rc<HashMap<String, String>>,
) -> Rc<Vec<Rc<ErrorNode>>> {
    Rc::new({
        let mut __result = Vec::new();
        for n in order.iter().cloned() {
            __result.extend(
                (*dag_emit_check_node_refs(n.clone(), key_to_id.clone()))
                    .iter()
                    .cloned(),
            );
        }
        __result
    })
}

pub fn build_dag_key_to_id(order: Rc<Vec<Rc<Node>>>) -> Rc<HashMap<String, String>> {
    Rc::new(
        order
            .clone()
            .iter()
            .cloned()
            .enumerate()
            .map(|(i, v)| (i as i64, v))
            .collect::<Vec<_>>(),
    )
    .iter()
    .cloned()
    .fold(
        v1_rt::rc_empty_map::<String, String>(),
        |acc: Rc<HashMap<String, String>>, pair: (i64, Rc<Node>)| {
            v1_rt::rc_map_insert(
                acc,
                crate::v1_compiler_dag_collect::dag_node_key(pair.1.clone()),
                v1_rt::concat("n".to_string(), (pair.0.clone()).to_string()),
            )
        },
    )
}

