pub fn serialize_typed_module(
    module: Rc<TypedModule>,
    key_to_id: Rc<HashMap<String, String>>,
) -> String {
    v1_rt::concat(
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            "{\"module\": ".to_string(),
                            serialize_node_ref(module.module.clone(), key_to_id.clone()),
                        ),
                        ", \"items\": ".to_string(),
                    ),
                    json_list(Rc::new({
                        let mut __result = Vec::new();
                        for item in module.items.clone().iter().cloned() {
                            __result.push(serialize_node_ref(item.clone(), key_to_id.clone()));
                        }
                        __result
                    })),
                ),
                ", \"item_registry_keys\": ".to_string(),
            ),
            json_list(Rc::new({
                let mut __result = Vec::new();
                for k in Rc::new(v1_rt::sorted_map_keys(&module.item_registry.clone()))
                    .iter()
                    .cloned()
                {
                    __result.push(crate::v1_compiler_dag_collect_support::json_quote(
                        k.clone(),
                    ));
                }
                __result
            })),
        ),
        "}".to_string(),
    )
}

pub fn serialize_dag_nodes_table(
    order: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    key_to_id: Rc<HashMap<String, String>>,
) -> String {
    Rc::new({
        let mut __result = Vec::new();
        for pair in Rc::new(
            order
                .clone()
                .iter()
                .cloned()
                .enumerate()
                .map(|(i, v)| (i as i64, v))
                .collect::<Vec<_>>(),
        )
        .iter()
        .cloned()
        {
            __result.push(v1_rt::concat(
                v1_rt::concat(
                    crate::v1_compiler_dag_collect_support::json_quote(v1_rt::concat(
                        "n".to_string(),
                        (pair.0.clone()).to_string(),
                    )),
                    ": ".to_string(),
                ),
                serialize_node_record(pair.1.clone(), source_indices.clone(), key_to_id.clone()),
            ));
        }
        __result
    })
    .join(&", ".to_string())
}

pub fn serialize_diagnostic(diagnostic: Rc<ErrorNode>) -> String {
    {
        let severity = "error".to_string();
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                "{\"severity\": ".to_string(),
                                                crate::v1_compiler_dag_collect_support::json_quote(
                                                    severity.clone(),
                                                ),
                                            ),
                                            ", \"message\": ".to_string(),
                                        ),
                                        crate::v1_compiler_dag_collect_support::json_quote(
                                            crate::v1_std_core::diagnostic_to_message(
                                                diagnostic.diagnostic.clone(),
                                            ),
                                        ),
                                    ),
                                    ", \"span\": ".to_string(),
                                ),
                                serialize_span(crate::v1_std_core::diagnostic_to_span(
                                    diagnostic.diagnostic.clone(),
                                )),
                            ),
                            ", \"module_name\": ".to_string(),
                        ),
                        json_optional_string(Some(diagnostic.module_name.clone())),
                    ),
                    ", \"category\": ".to_string(),
                ),
                "null".to_string(),
            ),
            "}".to_string(),
        )
    }
}

pub fn emit_dag_artifact(typed: Rc<ResolvedGraph>) -> Rc<EmitResult> {
    {
        let collected = crate::v1_compiler_dag_collect::collect_dag_nodes(typed.clone());
        let _ = v1_rt::trace_mark("compile.emit.dag.collect.done".to_string());
        if ((collected.collision_errors.clone().len() as i64) > 0) {
            return Rc::new(EmitResult {
                files: Rc::new(vec![]),
                diagnostics: collected.collision_errors.clone(),
            });
        }
        let order = collected.order.clone();
        let key_to_id = build_dag_key_to_id(order.clone());
        let ref_errors = dag_emit_ref_errors(order.clone(), key_to_id.clone());
        if ((ref_errors.clone().len() as i64) > 0) {
            return Rc::new(EmitResult {
                files: Rc::new(vec![]),
                diagnostics: ref_errors.clone(),
            });
        }
        let source_indices = dag_graph_source_indices(typed.clone());
        let nodes_json =
            serialize_dag_nodes_table(order.clone(), source_indices.clone(), key_to_id.clone());
        let modules_json = Rc::new({
            let mut __result = Vec::new();
            for m in typed.modules.clone().iter().cloned() {
                __result.push(serialize_typed_module(m.clone(), key_to_id.clone()));
            }
            __result
        })
        .join(&", ".to_string());
        let diagnostics_json = Rc::new({
            let mut __result = Vec::new();
            for d in typed.diagnostics.clone().iter().cloned() {
                __result.push(serialize_diagnostic(d.clone()));
            }
            __result
        })
        .join(&", ".to_string());
        let item_registry_json = Rc::new({
            let mut __result = Vec::new();
            for k in Rc::new(v1_rt::sorted_map_keys(&typed.item_registry.clone()))
                .iter()
                .cloned()
            {
                __result.push(crate::v1_compiler_dag_collect_support::json_quote(
                    k.clone(),
                ));
            }
            __result
        })
        .join(&", ".to_string());
        let json = v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        "{\n  \"version\": \"0.2.0\",\n  \"nodes\": {".to_string(),
                                        nodes_json.clone(),
                                    ),
                                    "},\n  \"modules\": [".to_string(),
                                ),
                                modules_json.clone(),
                            ),
                            "],\n  \"item_registry_keys\": [".to_string(),
                        ),
                        item_registry_json.clone(),
                    ),
                    "],\n  \"diagnostics\": [".to_string(),
                ),
                diagnostics_json.clone(),
            ),
            "],\n  \"files\": []\n}".to_string(),
        );
        let _ = v1_rt::trace_mark("compile.emit.dag.serialize.done".to_string());
        Rc::new(EmitResult {
            files: Rc::new(vec![Rc::new(TextFile {
                path: "dag-artifact.json".to_string(),
                content: json.clone(),
            })]),
            diagnostics: Rc::new(vec![]),
        })
    }
}

pub fn boundary_ref_error(names: Rc<Vec<String>>, ref_name: String) -> Rc<Vec<Rc<ErrorNode>>> {
    if {
        let mut __found = false;
        for n in names.iter().cloned() {
            if (n.clone() == ref_name.clone()) {
                __found = true;
                break;
            }
        }
        __found
    } {
        Rc::new(vec![])
    } else {
        Rc::new(vec![compile_bundle_error(v1_rt::concat(
            v1_rt::concat(
                "boundary references unknown artifact '".to_string(),
                ref_name.clone(),
            ),
            "'".to_string(),
        ))])
    }
}

pub fn validate_boundaries(plan: Rc<ArtifactPlan>) -> Rc<Vec<Rc<ErrorNode>>> {
    {
        let names = Rc::new({
            let mut __result = Vec::new();
            for a in plan.artifacts.clone().iter().cloned() {
                __result.push(a.name.clone());
            }
            __result
        });
        Rc::new({
            let mut __result = Vec::new();
            for b in plan.boundaries.clone().iter().cloned() {
                __result.extend(
                    (*v1_rt::concat(
                        boundary_ref_error(names.clone(), b.from_artifact.clone()),
                        boundary_ref_error(names.clone(), b.to_artifact.clone()),
                    ))
                    .iter()
                    .cloned(),
                );
            }
            __result
        })
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct EmittableGraph {
    graph: Rc<ResolvedGraph>,
}
impl EmittableGraph {
    pub fn graph(&self) -> Rc<ResolvedGraph> {
        self.graph.clone()
    }
}

pub fn emittable_graph(resolved: Rc<ResolvedPipelineResult>) -> Option<Rc<EmittableGraph>> {
    {
        let blocking = Rc::new({
            let mut __result = Vec::new();
            for d in resolved.diagnostics.clone().iter().cloned() {
                if crate::v1_std_core::is_interpreter_blocking_diagnostic(d.diagnostic.clone()) {
                    __result.push(d);
                }
            }
            __result
        });
        if ((blocking.clone().len() as i64) > 0) {
            std::option::Option::None
        } else {
            match resolved.graph.clone() {
                Some(typed) => Some(Rc::new(EmittableGraph {
                    graph: typed.clone(),
                })),
                std::option::Option::None => std::option::Option::None,
            }
        }
    }
}

pub fn emittable_graph_from_graph(typed: Rc<ResolvedGraph>) -> Rc<EmittableGraph> {
    Rc::new(EmittableGraph {
        graph: typed.clone(),
    })
}

pub fn emit_from_artifact_plan(
    emittable: Rc<EmittableGraph>,
    artifact_plan: Rc<ArtifactPlan>,
) -> Rc<EmitResult> {
    {
        let typed = emittable.graph();
        if ((artifact_plan.artifacts.clone().len() as i64) == 0) {
            return Rc::new(EmitResult {
                files: Rc::new(vec![]),
                diagnostics: Rc::new(vec![compile_bundle_error(
                    "compile_sources planned no artifacts".to_string(),
                )]),
            });
        }
        let boundary_diags = validate_boundaries(artifact_plan.clone());
        if ((boundary_diags.clone().len() as i64) > 0) {
            return Rc::new(EmitResult {
                files: Rc::new(vec![]),
                diagnostics: boundary_diags.clone(),
            });
        }
        let results = Rc::new({
            let mut __result = Vec::new();
            for artifact in artifact_plan.artifacts.clone().iter().cloned() {
                __result.push(emit_artifact(typed.clone(), artifact.clone()));
            }
            __result
        });
        let all_files = Rc::new({
            let mut __result = Vec::new();
            for r in results.iter().cloned() {
                __result.extend((*r.files.clone()).iter().cloned());
            }
            __result
        });
        let all_diags = Rc::new({
            let mut __result = Vec::new();
            for r in results.iter().cloned() {
                __result.extend((*r.diagnostics.clone()).iter().cloned());
            }
            __result
        });
        Rc::new(EmitResult {
            files: all_files.clone(),
            diagnostics: all_diags.clone(),
        })
    }
}

pub fn collect_diagnostics(parse_results: Rc<Vec<Rc<ParseResult>>>) -> Rc<Vec<Rc<ErrorNode>>> {
    parse_results.iter().cloned().fold(
        Rc::new(vec![]),
        |acc: Rc<Vec<Rc<ErrorNode>>>, pr: Rc<ParseResult>| match pr.error.clone() {
            Some(diag) => v1_rt::rc_list_push(acc.clone(), diag.clone()),
            std::option::Option::None => acc.clone(),
        },
    )
}

pub fn resolve_frontend_occurrence_transport(
    module_inputs: Rc<Vec<Rc<ModuleOccurrenceInput>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    occurrence_transport: Rc<OccurrenceTransport>,
) -> Rc<FrontendOccurrenceResolution> {
    match crate::std_occurrence_identity::occurrence_transport_refusal(occurrence_transport.clone())
    {
        Some(refusal) => Rc::new(FrontendOccurrenceResolution {
            graph: std::option::Option::None,
            diagnostics: Rc::new(vec![crate::v1_std_core::make_error_node(
                Rc::new(CompilerDiagnostic::OccurrenceTransportViolation {
                    refusal: refusal.clone(),
                }),
                "".to_string(),
            )]),
        }),
        std::option::Option::None => {
            let graph = crate::v1_compiler_resolve::resolve_modules_with_occurrence_transport(
                module_inputs.clone(),
                source_indices.clone(),
                occurrence_transport.clone(),
            );
            Rc::new(FrontendOccurrenceResolution {
                graph: Some(graph.clone()),
                diagnostics: graph.diagnostics.clone(),
            })
        }
    }
}

pub fn front_end_sources(sources: Rc<Vec<Rc<SourceFile>>>) -> Rc<FrontendResult> {
    {
        let prepared = Rc::new({
            let mut __result = Vec::new();
            for s in sources.iter().cloned() {
                __result.push({
                    let artifact = crate::v1_compiler_tokenize::tokenize_artifact(
                        s.content.clone(),
                        s.path.clone(),
                        dag_parse_environment(),
                    );
                    let si =
                        crate::v1_std_core::build_newline_index(s.path.clone(), s.content.clone());
                    Rc::new(FrontendPrepared {
                        tokens: artifact.tokens.clone(),
                        annotations: artifact.annotations.clone(),
                        source_length: v1_rt::string_length(&s.content.clone()),
                        newline_index: si.clone(),
                    })
                });
            }
            __result
        });
        let intern_table = prepared.iter().cloned().fold(
            crate::v1_std_core::empty_intern_table(),
            |t: Rc<InternTable>, p: Rc<FrontendPrepared>| {
                crate::v1_std_core::pre_intern_tokens(p.tokens.clone(), t)
            },
        );
        let parsed = prepared.iter().cloned().fold(
            Rc::new(FrontendAccum {
                parse_results: Rc::new(vec![]),
                module_inputs: Rc::new(vec![]),
                newline_indices: Rc::new(vec![]),
                intern_table: intern_table.clone(),
                occurrence_allocator:
                    crate::std_occurrence_identity::occurrence_id_allocator_initial(),
                annotations: crate::std_source_annotation::source_annotation_graph_empty(),
                annotation_diagnostics: Rc::new(vec![]),
            }),
            |acc: Rc<FrontendAccum>, p: Rc<FrontendPrepared>| {
                let parsed = crate::v1_compiler_parse::parse_with_table_in_occurrence_scope(
                    p.tokens.clone(),
                    v1_rt::rc_map_insert(
                        v1_rt::rc_empty_map::<String, Rc<NewlineIndex>>(),
                        p.newline_index.clone().file.clone(),
                        p.newline_index.clone(),
                    ),
                    acc.intern_table.clone(),
                    acc.occurrence_allocator.clone(),
                    dag_parse_environment(),
                );
                let bound = crate::v1_compiler_annotation_bind::admit_source_annotations(
                    parsed.occurrence_transport.clone(),
                    p.annotations.clone(),
                    p.source_length.clone(),
                );
                Rc::new(FrontendAccum {
                    parse_results: v1_rt::rc_list_push(
                        acc.parse_results.clone(),
                        parsed.result.clone(),
                    ),
                    module_inputs: match parsed.result.clone().module.clone() {
                        Some(parsed_module) => v1_rt::rc_list_push(
                            acc.module_inputs.clone(),
                            crate::v1_compiler_resolve::module_occurrence_input(
                                parsed_module.clone(),
                                parsed.occurrence_transport.clone(),
                            ),
                        ),
                        std::option::Option::None => acc.module_inputs.clone(),
                    },
                    newline_indices: v1_rt::rc_list_push(
                        acc.newline_indices.clone(),
                        p.newline_index.clone(),
                    ),
                    intern_table: parsed.intern_table.clone(),
                    occurrence_allocator: parsed.occurrence_allocator.clone(),
                    annotations: crate::std_source_annotation::source_annotation_graph_concat(
                        acc.annotations.clone(),
                        bound.graph.clone(),
                    ),
                    annotation_diagnostics: v1_rt::concat(
                        acc.annotation_diagnostics.clone(),
                        Rc::new({
                            let mut __result = Vec::new();
                            for d in bound.diagnostics.clone().iter().cloned() {
                                __result.push(crate::v1_std_core::make_error_node(
                                    d.clone(),
                                    p.newline_index.clone().file.clone(),
                                ));
                            }
                            __result
                        }),
                    ),
                })
            },
        );
        let parse_results = parsed.parse_results.clone();
        let newline_indices = parsed.newline_indices.clone();
        let parse_diagnostics = collect_diagnostics(parse_results.clone());
        let module_inputs = parsed.module_inputs.clone();
        let source_indices = newline_indices.iter().cloned().fold(
            v1_rt::rc_empty_map::<String, Rc<NewlineIndex>>(),
            |acc: Rc<HashMap<String, Rc<NewlineIndex>>>, si: Rc<NewlineIndex>| {
                v1_rt::rc_map_insert(acc, si.file.clone(), si.clone())
            },
        );
        let occurrence_transport = merge_occurrence_transports(Rc::new({
            let mut __result = Vec::new();
            for input in module_inputs.iter().cloned() {
                __result.push(
                    crate::v1_compiler_resolve::module_occurrence_input_transport(input.clone()),
                );
            }
            __result
        }));
        let resolution = resolve_frontend_occurrence_transport(
            module_inputs.clone(),
            source_indices.clone(),
            occurrence_transport.clone(),
        );
        Rc::new(FrontendResult {
            graph: resolution.graph.clone(),
            diagnostics: v1_rt::concat(
                v1_rt::concat(parse_diagnostics.clone(), resolution.diagnostics.clone()),
                parsed.annotation_diagnostics.clone(),
            ),
            newline_indices: newline_indices.clone(),
            intern_table: parsed.intern_table.clone(),
            occurrence_transport: occurrence_transport.clone(),
            annotations: parsed.annotations.clone(),
        })
    }
}

pub fn census_heads_item_is_fn_decl(item: Rc<Node>) -> bool {
    (((item.connective.clone() == Connective::NoConnective)
        && (item.body.clone() != std::option::Option::None))
        && (item.transport.clone() == std::option::Option::None))
}

pub fn census_heads_node(
    node: Rc<Node>,
    children: Rc<Vec<Rc<Node>>>,
    body: Option<Rc<Node>>,
) -> Rc<Node> {
    Rc::new(Node {
        occurrence_identity: node.occurrence_identity.clone(),
        name: node.name.clone(),
        ident: node.ident.clone(),
        span: node.span.clone(),
        ident_span: node.ident_span.clone(),
        children: children.clone(),
        connective: node.connective.clone(),
        params: node.params.clone(),
        inferred: node.inferred.clone(),
        return_cardinality: node.return_cardinality.clone(),
        uses: Rc::new(vec![]),
        body: body.clone(),
        transport: node.transport.clone(),
        properties: node.properties.clone(),
        type_annotation: node.type_annotation.clone(),
        is_self_recursive: node.is_self_recursive.clone(),
        has_non_tail_self_call: node.has_non_tail_self_call.clone(),
        match_pattern: std::option::Option::None,
        module_item_kind: node.module_item_kind.clone(),
        declaration_marker: node.declaration_marker.clone(),
        expr_data: Rc::new(ExprData::NoExprData),
    })
}

pub fn census_heads_module_item(item: Rc<Node>) -> Rc<Node> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        census_heads_node(
            item.clone(),
            Rc::new({
                let mut __result = Vec::new();
                for child in item.children.clone().iter().cloned() {
                    __result.push(census_heads_module_item(child.clone()));
                }
                __result
            }),
            if census_heads_item_is_fn_decl(item.clone()) {
                Some(crate::v1_compiler_parse::census_heads_body_stand_in())
            } else {
                std::option::Option::None
            },
        )
    })
}

pub fn census_heads_module_node(module: Rc<Node>) -> Rc<Node> {
    census_heads_node(
        module.clone(),
        Rc::new({
            let mut __result = Vec::new();
            for item in crate::v1_std_core::module_items(module.clone())
                .iter()
                .cloned()
            {
                __result.push(census_heads_module_item(item.clone()));
            }
            __result
        }),
        std::option::Option::None,
    )
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CensusFillParse {
    pub modules: Rc<Vec<Rc<Node>>>,
    pub newline_indices: Rc<Vec<Rc<NewlineIndex>>>,
    pub diagnostics: Rc<Vec<Rc<ErrorNode>>>,
    pub occurrence_transport: Rc<OccurrenceTransport>,
    pub annotations: Rc<SourceAnnotationGraph>,
}

#[derive(
    Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, serde::Serialize, serde::Deserialize,
)]
#[serde(tag = "_variant")]
pub enum CensusModuleRetention {
    RetainParsedModules,
    RetainDeclarationHeads,
}

pub fn census_retain_module(module: Rc<Node>, retention: CensusModuleRetention) -> Rc<Node> {
    match retention.clone() {
        CensusModuleRetention::RetainParsedModules => module.clone(),
        CensusModuleRetention::RetainDeclarationHeads => census_heads_module_node(module.clone()),
    }
}

pub fn census_retain_parse_result(
    result: Rc<ParseResult>,
    retention: CensusModuleRetention,
) -> Rc<ParseResult> {
    Rc::new(ParseResult {
        module: match result.module.clone() {
            Some(module_node) => Some(census_retain_module(module_node.clone(), retention.clone())),
            std::option::Option::None => std::option::Option::None,
        },
        error: result.error.clone(),
    })
}

pub fn parse_census_fill_sources_with(
    sources: Rc<Vec<Rc<SourceFile>>>,
    retention: CensusModuleRetention,
    environment: Rc<ParseEnvironment>,
) -> Rc<CensusFillParse> {
    {
        let parsed = sources.iter().cloned().fold(
            Rc::new(FrontendAccum {
                parse_results: Rc::new(vec![]),
                module_inputs: Rc::new(vec![]),
                newline_indices: Rc::new(vec![]),
                intern_table: crate::v1_std_core::empty_intern_table(),
                occurrence_allocator:
                    crate::std_occurrence_identity::occurrence_id_allocator_initial(),
                annotations: crate::std_source_annotation::source_annotation_graph_empty(),
                annotation_diagnostics: Rc::new(vec![]),
            }),
            |acc: Rc<FrontendAccum>, s: Rc<SourceFile>| {
                let artifact = crate::v1_compiler_tokenize::tokenize_artifact(
                    s.content.clone(),
                    s.path.clone(),
                    environment.clone(),
                );
                let p = Rc::new(FrontendPrepared {
                    tokens: artifact.tokens.clone(),
                    annotations: artifact.annotations.clone(),
                    source_length: v1_rt::string_length(&s.content.clone()),
                    newline_index: crate::v1_std_core::build_newline_index(
                        s.path.clone(),
                        s.content.clone(),
                    ),
                });
                let parsed = crate::v1_compiler_parse::parse_with_table_in_occurrence_scope(
                    p.tokens.clone(),
                    v1_rt::rc_map_insert(
                        v1_rt::rc_empty_map::<String, Rc<NewlineIndex>>(),
                        p.newline_index.clone().file.clone(),
                        p.newline_index.clone(),
                    ),
                    crate::v1_std_core::pre_intern_tokens(
                        p.tokens.clone(),
                        acc.intern_table.clone(),
                    ),
                    acc.occurrence_allocator.clone(),
                    environment.clone(),
                );
                let bound = crate::v1_compiler_annotation_bind::admit_source_annotations(
                    parsed.occurrence_transport.clone(),
                    p.annotations.clone(),
                    p.source_length.clone(),
                );
                let retained_result =
                    census_retain_parse_result(parsed.result.clone(), retention.clone());
                Rc::new(FrontendAccum {
                    parse_results: v1_rt::rc_list_push(
                        acc.parse_results.clone(),
                        retained_result.clone(),
                    ),
                    module_inputs: match retained_result.module.clone() {
                        Some(parsed_module) => v1_rt::rc_list_push(
                            acc.module_inputs.clone(),
                            crate::v1_compiler_resolve::module_occurrence_input(
                                parsed_module.clone(),
                                parsed.occurrence_transport.clone(),
                            ),
                        ),
                        std::option::Option::None => acc.module_inputs.clone(),
                    },
                    newline_indices: v1_rt::rc_list_push(
                        acc.newline_indices.clone(),
                        p.newline_index.clone(),
                    ),
                    intern_table: parsed.intern_table.clone(),
                    occurrence_allocator: parsed.occurrence_allocator.clone(),
                    annotations: crate::std_source_annotation::source_annotation_graph_concat(
                        acc.annotations.clone(),
                        bound.graph.clone(),
                    ),
                    annotation_diagnostics: v1_rt::concat(
                        acc.annotation_diagnostics.clone(),
                        Rc::new({
                            let mut __result = Vec::new();
                            for d in bound.diagnostics.clone().iter().cloned() {
                                __result.push(crate::v1_std_core::make_error_node(
                                    d.clone(),
                                    p.newline_index.clone().file.clone(),
                                ));
                            }
                            __result
                        }),
                    ),
                })
            },
        );
        let parse_results = parsed.parse_results.clone();
        let module_inputs = parsed.module_inputs.clone();
        Rc::new(CensusFillParse {
            modules: Rc::new({
                let mut __result = Vec::new();
                for input in module_inputs.iter().cloned() {
                    __result.push(crate::v1_compiler_resolve::module_occurrence_input_node(
                        input.clone(),
                    ));
                }
                __result
            }),
            newline_indices: parsed.newline_indices.clone(),
            diagnostics: v1_rt::concat(
                collect_diagnostics(parse_results.clone()),
                parsed.annotation_diagnostics.clone(),
            ),
            occurrence_transport: merge_occurrence_transports(Rc::new({
                let mut __result = Vec::new();
                for input in module_inputs.iter().cloned() {
                    __result.push(
                        crate::v1_compiler_resolve::module_occurrence_input_transport(
                            input.clone(),
                        ),
                    );
                }
                __result
            })),
            annotations: parsed.annotations.clone(),
        })
    }
}

